<?php
namespace App\Http\Controllers;
use App\Models\{Customer,EggProduct,Order}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class CustomerOrderController {
 public function home(){return view('customer.home');}
 public function create(){return view('customer.order',['products'=>EggProduct::where('status','active')->orderBy('product_name')->get()]);}
 public function store(Request $request){$d=$request->validate(['customer_name'=>'required|string|max:100','contact'=>'required|string|max:30','email'=>'nullable|email|max:150','address'=>'nullable|string|max:255','items'=>'required|array|min:1','items.*.product_id'=>'required|integer|exists:egg_products,id','items.*.quantity'=>'required|integer|min:1|max:1000']); $o=DB::transaction(function()use($d){$c=Customer::updateOrCreate(['contact'=>$d['contact']],['name'=>$d['customer_name'],'email'=>$d['email']??null,'address'=>$d['address']??null]);$o=Order::create(['customer_id'=>$c->id,'order_number'=>'INQ-'.now()->format('YmdHis').'-'.random_int(100,999),'order_date'=>now(),'estimated_total'=>0,'status'=>'pending']);$total=0;foreach($d['items'] as $i){$p=EggProduct::whereKey($i['product_id'])->where('status','active')->firstOrFail();$q=(int)$i['quantity'];$o->items()->create(['product_id'=>$p->id,'quantity'=>$q,'unit_price'=>$p->price]);$total += $q*(float)$p->price;}$o->update(['estimated_total'=>$total]);return $o;});$request->session()->put('customer_orders',array_values(array_unique(array_merge($request->session()->get('customer_orders',[]),[$o->id]))));return redirect()->route('customer.confirmation',$o);}
 public function confirmation(Request $r,Order $order){abort_unless(in_array($order->id,$r->session()->get('customer_orders',[]),true),403);$order->load('items.product','customer');return view('customer.confirmation',compact('order'));}
 public function myOrders(Request $r){$ids=$r->session()->get('customer_orders',[]);$orders=Order::with('items.product','customer')->whereIn('id',$ids?:[0])->latest('order_date')->get();return view('customer.my-orders',compact('orders'));}
 public function show(Request $r,Order $order){$ok=in_array($order->id,$r->session()->get('customer_orders',[]),true)||$r->query('track')===$order->order_number;abort_unless($ok,403);$order->load('items.product','customer');return view('customer.order-details',compact('order'));}
 public function track(Request $r){$d=$r->validate(['order_number'=>'required','contact'=>'required|string|max:30']);$o=Order::where('order_number',$d['order_number'])->whereHas('customer',fn($q)=>$q->where('contact',$d['contact']))->first();if(!$o)return back()->withErrors(['order_number'=>'Order number or contact does not match our records.']);return redirect()->route('customer.order.details',['order'=>$o,'track'=>$o->order_number]);}
}
